insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-113","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 0.10 M KCl standard with $\\kappa = 0.0129\\ \\mathrm{S\\ cm^{-1}}$ shows $R = 86\\ \\Omega$ in a cell. The cell constant is nearest","options":["$1.11\\ \\mathrm{cm^{-1}}$","$0.15\\ \\mathrm{cm^{-1}}$","$86\\ \\mathrm{cm^{-1}}$","$0.0129\\ \\mathrm{cm^{-1}}$"],"answer_index":0,"explanation":"$G = 1/86\\ \\mathrm{S}$, so $\\ell/A = \\kappa/G = 0.0129 \\times 86 \\approx 1.11\\ \\mathrm{cm^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance"},{"id":"che-ek-114","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Comparing $\\kappa$ and $\\Lambda_m$ as a strong electrolyte is diluted, the typical pattern is that","options":["$\\kappa$ decreases while $\\Lambda_m$ increases","both $\\kappa$ and $\\Lambda_m$ fall sharply","both $\\kappa$ and $\\Lambda_m$ rise equally","$\\Lambda_m$ falls while $\\kappa$ stays constant"],"answer_index":0,"explanation":"Fewer ions per cm$^3$ lower $\\kappa$, but each mole of electrolyte contributes more free ionic mobility, so $\\Lambda_m$ rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance"},{"id":"che-ek-115","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The slight increase of $\\Lambda_m$ of NaCl on dilution is attributed mainly to","options":["weaker interionic attractions, so ions migrate faster","fresh ionisation of previously undissociated NaCl molecules","a change in the Faraday constant","conversion of NaCl into a weak electrolyte"],"answer_index":0,"explanation":"NaCl is already fully dissociated. Dilution reduces ion-atmosphere drag (Debye–Hückel–Onsager), raising molar conductivity a little.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance"},{"id":"che-ek-116","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 0.050 M solution in a cell of constant $1.20\\ \\mathrm{cm^{-1}}$ has $R = 50\\ \\Omega$. $\\Lambda_m$ of the solute is","options":["$480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$24\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$0.48\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$1200\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$"],"answer_index":0,"explanation":"$\\kappa = (1/50)\\times 1.20 = 0.024\\ \\mathrm{S\\ cm^{-1}}$; then $\\Lambda_m = 1000\\times 0.024/0.050 = 480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"conductance"},{"id":"che-ek-117","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Kohlrausch's law of independent migration states that $\\Lambda_m^\\circ$ of an electrolyte is","options":["the sum of the limiting ionic conductivities of its cation and anion","equal to the product $\\lambda_+^\\circ \\times \\lambda_-^\\circ$","independent of the identities of the two ions","measurable only for metals, not for salts"],"answer_index":0,"explanation":"At infinite dilution each ion migrates independently, so $\\Lambda_m^\\circ = \\nu_+\\lambda_+^\\circ + \\nu_-\\lambda_-^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-118","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a 1:1 salt MX the limiting molar conductivity may be written","options":["$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) + \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+)/\\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) - \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = 2\\lambda^\\circ(\\mathrm{M}^+)$ always"],"answer_index":0,"explanation":"One mole of MX yields one mole of each ion, so the ionic contributions simply add.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-119","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Limiting molar conductivity of a weak electrolyte such as ethanoic acid is obtained by","options":["combining $\\Lambda_m^\\circ$ values of suitable strong electrolytes, not by plotting $\\Lambda_m$ versus $\\sqrt{c}$","extrapolating a Kohlrausch $\\sqrt{c}$ graph of the weak acid itself","measuring $\\kappa$ of distilled water alone","equating $\\Lambda_m$ at 1 M to $\\Lambda_m^\\circ$"],"answer_index":0,"explanation":"A weak acid is far from fully ionised even when dilute, so the $\\sqrt{c}$ plot does not give a reliable intercept.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-120","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Degree of dissociation of a weak electrolyte is estimated from conductivities as","options":["$\\alpha = \\Lambda_m / \\Lambda_m^\\circ$","$\\alpha = \\Lambda_m^\\circ / \\Lambda_m$","$\\alpha = \\Lambda_m \\times \\Lambda_m^\\circ$","$\\alpha = \\kappa / \\Lambda_m$"],"answer_index":0,"explanation":"At a given concentration the fraction ionised is the ratio of the observed molar conductivity to the infinite-dilution value.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-121","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A practical use of Kohlrausch's law is the evaluation of","options":["$\\Lambda_m^\\circ$ of a poorly conducting weak acid from data on strong salts and acids","the Faraday constant from a copper voltameter","the order of a homogeneous reaction","the standard hydrogen electrode potential"],"answer_index":0,"explanation":"Typical combination: $\\Lambda_m^\\circ(\\mathrm{CH_3COOH}) = \\Lambda_m^\\circ(\\mathrm{CH_3COONa}) + \\Lambda_m^\\circ(\\mathrm{HCl}) - \\Lambda_m^\\circ(\\mathrm{NaCl})$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-122","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Limiting molar conductivity $\\Lambda_m^\\circ$ refers to the molar conductivity","options":["extrapolated to infinite dilution, where ions no longer hinder one another","measured in a saturated solution","of the solid crystal before it dissolves","at the boiling point of the solvent only"],"answer_index":0,"explanation":"Infinite dilution removes ion–ion interactions, so each ion contributes its characteristic $\\lambda^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-123","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Among common aqueous ions, the unusually large $\\lambda^\\circ$ belongs to","options":["$\\mathrm{H}^+$ (and also $\\mathrm{OH}^-$)","$\\mathrm{Li}^+$ only, because it is the lightest metal ion","$\\mathrm{ClO_4}^-$ because it is bulky","every alkali-metal cation equally"],"answer_index":0,"explanation":"Grotthuss proton/hydroxide hopping through the hydrogen-bond network gives $\\mathrm{H}^+$ and $\\mathrm{OH}^-$ exceptional mobility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch"},{"id":"che-ek-124","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Given $\\Lambda_m^\\circ/\\mathrm{S\\ cm^2\\ mol^{-1}}$ of CH$_3$COONa = 91, HCl = 426 and NaCl = 126, $\\Lambda_m^\\circ$ of CH$_3$COOH is","options":["391","643","209","335"],"answer_index":0,"explanation":"$\\Lambda_m^\\circ(\\mathrm{HOAc}) = 91 + 426 - 126 = 391\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$ by Kohlrausch combination.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"kohlrausch"},{"id":"che-ek-125","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A weak acid has $\\Lambda_m = 16\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$ and $\\Lambda_m^\\circ = 400\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$. Its degree of dissociation is","options":["0.040","0.40","25","0.0040"],"answer_index":0,"explanation":"$\\alpha = \\Lambda_m/\\Lambda_m^\\circ = 16/400 = 0.040$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"kohlrausch"},{"id":"che-ek-126","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Which set of limiting molar conductivities yields $\\Lambda_m^\\circ$ of NH$_4$OH?","options":["$\\Lambda_m^\\circ(\\mathrm{NH_4Cl}) + \\Lambda_m^\\circ(\\mathrm{NaOH}) - \\Lambda_m^\\circ(\\mathrm{NaCl})$","$\\Lambda_m^\\circ(\\mathrm{NH_4Cl}) - \\Lambda_m^\\circ(\\mathrm{NaOH})$","$\\Lambda_m^\\circ(\\mathrm{NaOH})$ alone","$\\Lambda_m^\\circ(\\mathrm{HCl}) + \\Lambda_m^\\circ(\\mathrm{NaOH})$"],"answer_index":0,"explanation":"Adding NH$_4$Cl and NaOH supplies NH$_4^+$ and OH$^-$; subtracting NaCl removes the spectator Na$^+$ and Cl$^-$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"kohlrausch"},{"id":"che-ek-127","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a weak monobasic acid, $K_a$ is related to the conductivity ratio $\\alpha$ and the molarity $c$ by","options":["$K_a \\approx \\alpha^2 c$","$K_a = \\alpha / c$","$K_a = \\alpha^2 / c$","$K_a = c / \\alpha^2$"],"answer_index":0,"explanation":"Ostwald dilution: $K_a = \\alpha^2 c /(1-\\alpha) \\approx \\alpha^2 c$ when $\\alpha \\ll 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"kohlrausch"},{"id":"che-ek-128","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ethanoic acid at $0.010\\ \\mathrm{M}$ has $\\Lambda_m = 16.0$ and $\\Lambda_m^\\circ = 390\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$. $K_a$ is nearest","options":["$1.7 \\times 10^{-5}$","$4.1 \\times 10^{-2}$","$1.6 \\times 10^{-3}$","$3.9 \\times 10^{-1}$"],"answer_index":0,"explanation":"$\\alpha = 16/390 \\approx 0.041$; then $K_a \\approx \\alpha^2 c = (0.041)^2 \\times 0.010 \\approx 1.7 \\times 10^{-5}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"kohlrausch"},{"id":"che-ek-129","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A galvanic (voltaic) cell is a device that","options":["converts chemical energy of a spontaneous redox change into electrical energy","uses an external battery to force a non-spontaneous reaction","stores charge on two metal plates like a capacitor","measures conductance of an electrolyte only"],"answer_index":0,"explanation":"In a galvanic cell a spontaneous cell reaction drives electrons through an external circuit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-130","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Inside a working galvanic cell, the cathode is the electrode at which","options":["reduction of the oxidant takes place","the reductant loses electrons","the salt bridge is oxidised","current is carried by neutrons"],"answer_index":0,"explanation":"By definition the cathode is the reduction site. In a galvanic cell it is the positive terminal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-131","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The salt bridge in a galvanic cell is provided mainly to","options":["maintain electrical neutrality in the two half-cells","supply the electrons that travel in the wire","raise the standard electrode potentials","keep the two metals from touching the solution"],"answer_index":0,"explanation":"Ions from the bridge migrate to cancel charge build-up so the cell can continue to operate.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"},{"id":"che-ek-132","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The standard hydrogen electrode is assigned, by convention, an $E^\\circ$ of","options":["$0.00\\ \\mathrm{V}$","$+1.00\\ \\mathrm{V}$","$-0.76\\ \\mathrm{V}$","$+0.34\\ \\mathrm{V}$"],"answer_index":0,"explanation":"SHE ($a_{\\mathrm{H}^+} = 1$, $p_{\\mathrm{H_2}} = 1\\ \\mathrm{bar}$) is the reference zero of the $E^\\circ$ scale.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-113","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-114","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-115","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-116","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-117","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-118","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-119","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-120","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-121","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-122","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-123","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-124","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-125","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-126","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-127","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-128","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-129","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-130","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-131","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-132","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
